g = primitives.call(name='ground_robocasa_visual_target', entity_name='drawer_obj', camera_name='robot0_agentview_left', world_position=[2.9733972549438477, -0.36803507804870605, 0.7651695609092712])
eh = None
if g.ok:
    o = g.output
    try:
        eh = o.get('evidence_handle') if isinstance(o, dict) else None
    except Exception:
        eh = None
result = {'ground_ok': g.ok, 'eh': eh, 'out': str(g.output)[:800]}
print(result)
if eh:
    m = primitives.call(name='move_robocasa_ee_to', evidence_handles=[eh], target_name='drawer_obj', offset=[0.15, 0.0, 0.0], gripper_command=-1.0, horizon=150)
    result2 = {'move_ok': m.ok, 'out': str(m.output)[:800]}
    print(result2)

# Ground the drawer handle by world position (drawer front faces +x toward robot), then approach
g = primitives.call(name='ground_robocasa_visual_target', entity_name='drawer', camera_name='robot0_agentview_left', world_position=[3.22, -0.3, 0.785])
eh = None
if g.ok and isinstance(g.output, dict):
    eh = g.output.get('evidence_handle')
    if eh is None:
        d = g.output.get('data')
        if isinstance(d, dict):
            eh = d.get('evidence_handle')
result = {'ground_ok': g.ok, 'eh': eh, 'gout': str(g.output)[:600]}
print(result)
if eh:
    m = primitives.call(name='move_robocasa_ee_to', evidence_handles=[eh], target_position=[3.32, -0.3, 0.80], gripper_command=-1.0, horizon=200)
    result['move_ok'] = m.ok
    result['mout'] = str(m.output)[:600]
    print({'move_ok': m.ok, 'mout': str(m.output)[:600]})

# Try to find a drawer segmentation instance, ground it, then approach the drawer front
seg_id = None
obs = primitives.call(name='observe_robocasa_rgbd', camera_name='robot0_agentview_left', query='drawer')
if obs.ok and isinstance(obs.output, dict):
    inst = obs.output.get('segmentation_instances') or obs.output.get('instances') or obs.output.get('segmentation') or []
    if isinstance(inst, dict):
        inst = [dict(id=k, name=v) for k, v in inst.items()]
    for it in inst:
        try:
            nm = str(it.get('name', it.get('label', ''))).lower()
            if 'drawer' in nm and seg_id is None:
                seg_id = it.get('id', it.get('segmentation_id'))
        except Exception:
            pass
result = {'obs_ok': obs.ok, 'seg_id': seg_id, 'obs': str(obs.output)[:500]}
print(result)

eh = None
if seg_id is not None:
    try:
        g = primitives.call(name='ground_robocasa_visual_target', entity_name='drawer', camera_name='robot0_agentview_left', segmentation_id=int(seg_id), prompt='left drawer handle')
    except Exception as e:
        g = None
        print('ground_exc', e)
    if g is not None and g.ok and isinstance(g.output, dict):
        eh = g.output.get('evidence_handle')
        print('ground_seg', str(g.output)[:400])
if eh is None:
    for cam in ['robot0_agentview_left', 'robot0_agentview_right']:
        g = primitives.call(name='ground_robocasa_visual_target', entity_name='drawer', camera_name=cam, world_position=[3.2, -0.3, 0.785], prompt='left drawer handle')
        print('ground_wp', cam, g.ok, str(g.output)[:400])
        if g.ok and isinstance(g.output, dict) and g.output.get('evidence_handle'):
            eh = g.output.get('evidence_handle')
            break
result['eh'] = eh
if eh:
    m = primitives.call(name='move_robocasa_ee_to', evidence_handles=[eh], target_position=[3.30, -0.3, 0.80], gripper_command=-1.0, horizon=200)
    result['move_ok'] = m.ok
    result['mout'] = str(m.output)[:500]
    print({'move_ok': m.ok, 'mout': str(m.output)[:500]})
else:
    m = primitives.call(name='move_robocasa_ee_to', evidence_handles=[], target_position=[3.30, -0.3, 0.80], gripper_command=-1.0, horizon=200)
    result['move_noeh_ok'] = m.ok
    result['mout'] = str(m.output)[:500]
    print({'move_noeh_ok': m.ok, 'mout': str(m.output)[:500]})

